class FrappeClient {
  constructor() {
    this.baseURL = "";
    this.csrfToken = window.frappe?.csrf_token || "";
  }

  async getHeaders() {
    return {
      "Content-Type": "application/json",
      "X-Frappe-CSRF-Token": this.csrfToken,
    };
  }

  async request(url, options = {}) {
    const config = {
      headers: await this.getHeaders(),
      ...options,
    };

    try {
      const response = await fetch(url, config);

      if (!response.ok) {
        const error = await response.json().catch(() => ({}));
        const messages =
          error._server_messages && JSON.parse(error._server_messages);
        const parsedMessage = messages ? JSON.parse(messages) : error;

        throw new Error(parsedMessage?.message || error);
      }

      return await response.json();
    } catch (error) {
      throw error;
    }
  }

  async get(doctype, name = null, filters = {}) {
    let url = `/api/resource/${doctype}`;

    if (name) {
      url += `/${name}`;
    } else if (Object.keys(filters).length > 0) {
      const params = new URLSearchParams();
      Object.entries(filters).forEach(([key, value]) => {
        params.append(key, value);
      });
      url += `?${params.toString()}`;
    }

    return this.request(url);
  }

  async post(doctype, data) {
    const url = `/api/resource/${doctype}`;
    const payload = {
      doctype: doctype,
      ...data,
    };

    return this.request(url, {
      method: "POST",
      body: JSON.stringify(payload),
    });
  }

  async update(doctype, name, data) {
    const url = `/api/resource/${doctype}/${name}`;
    return this.request(url, {
      method: "PUT",
      body: JSON.stringify(data),
    });
  }

  async delete(doctype, name) {
    const url = `/api/resource/${doctype}/${name}`;

    return this.request(url, {
      method: "DELETE",
    });
  }

  async setValue(doctype, name, fieldname, value) {
    const url = `/api/method/frappe.client.set_value`;
    const payload = {
      doctype: doctype,
      name: name,
      fieldname: fieldname,
    };

    if (value !== undefined) {
      payload.value = value;
    }

    return this.request(url, {
      method: "POST",
      body: JSON.stringify(payload),
    });
  }

  async runDocMethod(doctype, name, method, args = {}) {
    const url = `/api/method/frappe.client.run_doc_method`;
    const payload = {
      doctype: doctype,
      name: name,
      method: method,
      args: args,
    };

    return this.request(url, {
      method: "POST",
      body: JSON.stringify(payload),
    });
  }

  async call(method, args = {}, options = {}) {
    const url = `/api/method/${method}`;

    // If options.useQuery is true, send parameters as query string with GET request
    if (options.useQuery) {
      const queryString = new URLSearchParams(args).toString();
      const queryUrl = queryString ? `${url}?${queryString}` : url;

      return this.request(queryUrl, {
        method: "GET",
      });
    }

    // Default behavior: POST request with body
    return this.request(url, {
      method: "POST",
      body: JSON.stringify(args),
    });
  }

  async getDoc(doctype, name, filters = {}) {
    return this.get(doctype, name, filters);
  }

  async getDocList(
    doctype,
    { filters = [], fields = [], limit = 20, start = 0 } = {},
  ) {
    const params = new URLSearchParams();

    if (filters.length > 0) {
      params.append("filters", JSON.stringify(filters));
    }

    if (fields.length > 0) {
      params.append("fields", JSON.stringify(fields));
    }

    params.append("limit_page_length", limit);
    params.append("limit_start", start);

    const url = `/api/resource/${doctype}?${params.toString()}`;
    return this.request(url);
  }

  async count(doctype, filters = []) {
    const params = new URLSearchParams();

    if (filters.length > 0) {
      params.append("filters", JSON.stringify(filters));
    }

    const url = `/api/resource/${doctype}/count?${params.toString()}`;
    return this.request(url);
  }

  async uploadFile(file, options = {}) {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      const formData = new FormData();

      formData.append("file", file, file.name);
      formData.append("is_private", options.private ? "1" : "0");
      formData.append("folder", options.folder || "Home");
      if (options.doctype && options.docname) {
        formData.append("doctype", options.doctype);
        formData.append("docname", options.docname);
        if (options.fieldname) formData.append("fieldname", options.fieldname);
      }

      xhr.open(
        "POST",
        options.uploadEndpoint || "/api/method/upload_file",
        true,
      );
      xhr.setRequestHeader("Accept", "application/json");

      if (this.csrfToken) {
        xhr.setRequestHeader("X-Frappe-CSRF-Token", this.csrfToken);
      }

      xhr.onreadystatechange = () => {
        if (xhr.readyState !== XMLHttpRequest.DONE) return;
        if (xhr.status === 200) {
          let r;
          try {
            r = JSON.parse(xhr.responseText);
          } catch {
            r = xhr.responseText;
          }
          resolve(r.message || r);
        } else {
          let error = "Upload failed";
          try {
            const err = JSON.parse(xhr.responseText);
            error = err._error_message || err.message || error;
          } catch {
            // use default error message
          }
          reject(new Error(error));
        }
      };

      xhr.onerror = () => reject(new Error("Network error during upload"));
      xhr.send(formData);
    });
  }

  setCSRFToken(token) {
    this.csrfToken = token;
  }
}

window.frappeClient = new FrappeClient();
